/**
 * Minh & Thủy wear their wedding outfits for the whole story (no outfit
 * transformation). Their atlases are generated by
 * scripts/build-wedding-characters.py: 48 × 48 frames named
 * `<direction>-<pose>[-bq]`, feet on y = 42, body ≈ 14 × 29 art px
 * (Thủy's gown is up to ≈ 19 px wide at the hem).
 */

export const SHEET = {
  frameWidth: 48,
  frameHeight: 48,
  originX: 0.5,
  originY: 42.5 / 48, // anchor between the feet → `y` is the ground
  bodyWidth: 14,
  bodyHeight: 29,
};

export const DIRECTIONS = ['down', 'left', 'right', 'up'];

export const ANIM = {
  walkFrameRate: 8, // at the reference walking speed
  walkSpeed: 34, // art px / second — an unhurried wedding stroll
  blinkEvery: [2600, 5200],
  blinkDuration: 130,
};

/** Frame name helper: `down-stand`, `left-walk2-bq`, … */
export const frameName = (dir, pose, variant = '') => `${dir}-${pose}${variant}`;

/**
 * Per-character animation recipes. Durations are in ms.
 * Every list is played per direction unless marked `fixed`.
 */
